BEGIN;
-- Extend the existing validated JSON profile without rewriting legacy partner types.
CREATE OR REPLACE FUNCTION maintenance_private.registration_profile(profile jsonb,required boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SECURITY INVOKER SET search_path='' AS $$
DECLARE schema_data jsonb:=$fields$[["tipos_oficina","Tipos de oficina","multi",["Oficina mecânica","Auto elétrica","Funilaria e pintura","Borracharia","Concessionária","Auto center","Guincho e socorro","Lavagem","Tacógrafo e rastreador","Outros"]],["inscricao_estadual","Inscrição estadual"],["inscricao_municipal","Inscrição municipal"],["cnae","CNAE principal"],["regime_tributario","Regime tributário","select",["Não informado","Simples Nacional","Lucro Presumido","Lucro Real","MEI","Outro"]],["ano_fundacao","Ano de fundação","number",1900,2100],["site","Site"],["responsavel_legal","Responsável legal"],["cargo_responsavel","Cargo do responsável"],["rede_concessionaria","Rede / concessionária / grupo"],["comercial_nome","Contato comercial"],["comercial_telefone","Telefone comercial","tel"],["comercial_email","E-mail comercial","email"],["operacao_nome","Responsável pela operação"],["operacao_telefone","Telefone da operação","tel"],["operacao_email","E-mail da operação","email"],["financeiro_nome","Contato financeiro"],["financeiro_telefone","Telefone financeiro","tel"],["financeiro_email","E-mail financeiro","email"],["emergencia_nome","Contato de emergência"],["emergencia_telefone","Telefone de emergência","tel"],["canal_orcamento","Canal preferido para orçamento","select",["WhatsApp","E-mail","Telefone","Portal"]],["canal_andamento","Canal para acompanhamento","select",["WhatsApp","E-mail","Telefone","Portal"]],["marcas","Marcas atendidas","multi",["Agrale","Audi","BMW","BYD","CAOA Chery","Chevrolet","Citroën","DAF","Fiat","Ford","Honda","Hyundai","Iveco","JAC","Jeep","Kia","Land Rover","MAN","Mercedes-Benz","Mitsubishi","Nissan","Peugeot","RAM","Renault","Scania","Shacman","Toyota","Volkswagen","Volvo"]],["servicos","Serviços prestados","multi",["Mecânica geral","Motor","Câmbio manual","Câmbio automático","Embreagem","Freios","Suspensão","Direção","Elétrica","Eletrônica / diagnóstico","Injeção diesel","Injeção eletrônica","Ar-condicionado","Arrefecimento","Troca de óleo e filtros","Pneus e borracharia","Alinhamento e balanceamento","Funilaria e pintura","Solda e caldeiraria","Implementos e carretas","Hidráulica / pneumática","Tacógrafo","Rastreamento","Inspeção veicular","Socorro / guincho","Lavagem / higienização"]],["modalidades","Tipos de atendimento","multi",["Preventiva","Corretiva","Preditiva","Diagnóstico","Revisão","Inspeção","Emergencial","Garantia"]],["combustiveis","Motorização / combustível","multi",["Diesel","Gasolina","Etanol","Flex","GNV","Elétrico","Híbrido"]],["restricoes_veiculos","Restrições de marcas / modelos / veículos","textarea"],["modelos_especificos","Modelos e linhas com especialização","textarea"],["servicos_terceirizados","Serviços terceirizados e parceiros","textarea"],["regiao_atendida","Cidades / região atendida","textarea"],["raio_atendimento_km","Raio de atendimento (km)","number",0,10000],["atendimento_externo","Atendimento externo / móvel","bool"],["retira_entrega","Retira e entrega veículo","bool"],["estacionamento_seguro","Pátio / estacionamento seguro","bool"],["equipamentos","Equipamentos disponíveis","multi",["Scanner multimarcas","Scanner diesel","Elevador leve","Elevador pesado","Rampa de alinhamento","Valeta","Balança","Bancada de injeção","Socorro móvel","Guincho leve","Guincho pesado"]],["boxes","Número de boxes","number",0,500],["capacidade_dia","Capacidade de veículos por dia","number",0,1000],["equipe_tecnica","Número de técnicos","number",0,1000],["altura_max_m","Altura máxima atendida (m)","number",0,20],["peso_max_t","Peso máximo atendido (t)","number",0,500],["certificacoes","Certificações e qualificações (descrição)","textarea"],["garantia_dias","Garantia dos serviços (dias)","number",0,3650],["garantia_condicoes","Condições / cobertura de garantia","textarea"],["prazo_orcamento_h","Prazo estimado para orçamento (horas)","number",0,8760],["prazo_resposta_h","Prazo estimado de resposta (horas)","number",0,8760],["pecas","Política de peças","multi",["Originais","Genuínas","Paralelas homologadas","Remanufaturadas","Peças fornecidas pelo cliente"]],["restricoes_acesso","Referência / acesso para veículos pesados","textarea"],["aceita_faturado","Aceita pagamento faturado","select",["Sim","Não","Sujeito à análise"]],["formas_pagamento","Formas de pagamento","multi",["Boleto faturado","PIX","Transferência","Cartão de crédito","Cartão de débito","Dinheiro"]],["prazos_faturado","Prazos de faturamento disponíveis","multi",["7 dias","10 dias","14 dias","15 dias","21 dias","28 dias","30 dias","45 dias","60 dias","90 dias"]],["dia_faturamento","Dia / regra de fechamento do faturamento"],["limite_faturado","Limite de crédito sujeito a cadastro (R$)","number",0,100000000],["emite_nf","Emite nota fiscal","select",["Sim","Não"]],["nf_servico_pecas","Nota fiscal de serviços e peças","select",["Separadas","Conjugada","Somente serviços","Somente peças"]],["exige_os","Exige OS / pedido de compra para faturar","bool"],["exige_aprovacao","Só executa após aprovação formal","bool"],["exigencias_cadastro","Documentos / requisitos para liberar faturamento (descrever)","textarea"],["condicoes_comerciais","Regras de cobrança, parcelamento e condições adicionais","textarea"],["taxa_deslocamento","Taxa / condições de deslocamento e socorro","textarea"],["diferenciais","Diferenciais da oficina","textarea"],["observacoes","Observações e informações adicionais","textarea"]]$fields$::jsonb;field jsonb;k text;v jsonb;typ text;opts jsonb;n numeric;BEGIN
 IF profile IS NULL OR jsonb_typeof(profile)<>'object' OR octet_length(profile::text)>60000 THEN RAISE EXCEPTION 'Perfil cadastral inválido.';END IF;
 FOR k IN SELECT jsonb_object_keys(profile) LOOP IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(schema_data) f WHERE f->>0=k) THEN RAISE EXCEPTION 'Campo de perfil não permitido: %',k;END IF;END LOOP;
 FOR field IN SELECT value FROM jsonb_array_elements(schema_data) LOOP k:=field->>0;typ:=coalesce(field->>2,'text');v:=profile->k;
 IF v IS NULL OR v='null'::jsonb OR v='""'::jsonb THEN CONTINUE;END IF;
 IF typ='multi' THEN IF jsonb_typeof(v)<>'array' OR jsonb_array_length(v)>60 THEN RAISE EXCEPTION 'Lista inválida: %',k;END IF;IF EXISTS(SELECT 1 FROM jsonb_array_elements(v) x WHERE jsonb_typeof(x)<>'string' OR length(x#>>'{}') NOT BETWEEN 1 AND 100) THEN RAISE EXCEPTION 'Opção inválida: %',k;END IF;
 ELSIF typ='number' THEN IF v#>>'{}' !~ '^[0-9]+([.][0-9]{1,2})?$' THEN RAISE EXCEPTION 'Número inválido: %',k;END IF;n:=(v#>>'{}')::numeric;IF k=ANY(ARRAY['ano_fundacao','boxes','capacidade_dia','equipe_tecnica','garantia_dias']) AND n<>trunc(n) THEN RAISE EXCEPTION 'Informe um número inteiro: %',k;END IF;IF n<(field->>3)::numeric OR n>(field->>4)::numeric THEN RAISE EXCEPTION 'Número fora do limite: %',k;END IF;
 ELSIF typ='bool' THEN IF jsonb_typeof(v)<>'boolean' THEN RAISE EXCEPTION 'Opção inválida: %',k;END IF;
 ELSE IF jsonb_typeof(v)<>'string' OR length(v#>>'{}')>(CASE WHEN typ='textarea' THEN 4000 ELSE 200 END) THEN RAISE EXCEPTION 'Texto inválido: %',k;END IF;
 IF typ='select' AND NOT (field->3) ? (v#>>'{}') THEN RAISE EXCEPTION 'Seleção inválida: %',k;END IF;
 IF typ='email' AND v#>>'{}' !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' THEN RAISE EXCEPTION 'E-mail inválido: %',k;END IF;
 IF typ='tel' AND regexp_replace(v#>>'{}','[^0-9]','','g') !~ '^(55)?[1-9][0-9][2-9][0-9]{7,8}$' THEN RAISE EXCEPTION 'Telefone inválido: %',k;END IF;
 END IF;END LOOP;
 IF required THEN FOR k IN SELECT unnest(ARRAY['marcas','servicos','modalidades','formas_pagamento']) LOOP IF coalesce(jsonb_array_length(profile->k),0)=0 THEN RAISE EXCEPTION 'Selecione opções em %.',k;END IF;END LOOP;FOR k IN SELECT unnest(ARRAY['aceita_faturado','emite_nf','responsavel_legal']) LOOP IF nullif(btrim(profile->>k),'') IS NULL THEN RAISE EXCEPTION 'Preencha %.',k;END IF;END LOOP;END IF;RETURN profile;END $$;
COMMIT;
